237	     *  today on or after the setting's date), the next of the claim's period, <period name>-<n>, or of
238	     *  claims in no period, X-<n>; otherwise the sheet's next sheet-wide number. */
239	    private String nextNumber(String sheetId, Claim claim) {
240	        LocalDate from = settings.periodNumberingFrom(sheetId);
241	        if (from == null || sheets.today(sheetId).isBefore(from)) {
242	            return Integer.toString(sheets.nextClaimNumber(sheetId));
243	        }
244	        Period period = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
245	                .filter((p) -> p.contains(claim.getDate())).findFirst().orElse(null);
246	        if (period == null) return "X-" + sheets.nextSequenceNumber(sheetId, "none");
247	        return period.getName() + "-" + sheets.nextSequenceNumber(sheetId, "period:" + period.getId());
248	    }
249	
250	    /** Whether the user is a clerk settling a claim whose due is above the sheet's clerk limit. */
251	    private boolean isAboveClerkLimit(String sheetId, String user, BigDecimal due) {
252	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
253	        BigDecimal limit = settings.clerkLimit(sheetId);
254	        return limit != null && due.compareTo(limit) > 0;
255	    }
