257	    /** Refuse a change to a claim dated inside a closed period. The sheet is locked first, as closing
258	     *  a period locks it, so a claim cannot change in a period while it is being closed. */
259	    private void refuseIfClosed(String sheetId, LocalDate date) {
260	        sheetRows.findForUpdate(sheetId);
261	        if (periods.isClosedOn(sheetId, date)) {
262	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is dated inside a closed period.");
263	        }
264	    }
