266	    /** Refuse a correction (a negative amount) unless it names, by number, a settled claim of the same person. */
267	    private void refuseIfNotCorrecting(String sheetId, long personId, BigDecimal amount, String corrects) {
268	        if (amount.signum() >= 0) return;
269	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
270	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).isPresent();
271	        if (!settled) {
272	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
273	                    "A negative amount must name, by number, a settled claim of the same person that it corrects.");
274	        }
275	    }
