277	    /** Refuse a claim dated after its person's retirement date. */
278	    private static void refuseIfRetired(Person person, LocalDate date) {
279	        if (person.isRetiredOn(date)) {
280	            throw new ResponseStatusException(HttpStatus.CONFLICT,
281	                    "The claim is dated after " + person.getName() + " retired.");
