291	     *  overdue (the charge is never bound by a statement); null when the figure is n/a. */
292	    public BigDecimal due(String sheetId, Person person, Claim claim) {
293	        return LateCharge.dueOf(claim, figure(sheetId, person, claim), sheets.today(sheetId),
294	                settings.latePct(sheetId), rounding(sheetId, claim));
295	    }
