297	    /** The figure under the claim's due, before any late charge: the due fixed when it was settled, else the figure
298	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
299	     *  null when that is n/a. */
300	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
301	        if (claim.getSettledDue() != null) return claim.getSettledDue();
302	        if (claim.isBound()) return claim.getStatedDue();
303	        return dueNow(sheetId, person, claim);
304	    }
